        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "Cos'è la filosofia? Scusate il mio conservatorismo banale, ma non trovo ancora di meglio che la definizione che ne dà Aristotele nella Metafisica: è la risposta a un atto di meraviglia.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "Cosa è il leghismo se non la storia di un movimento che non legge?", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "È bello qualcosa che, se fosse nostro, ci rallegrerebbe, ma che rimane tale anche se appartiene a qualcun altro.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "Ecco la vera tecnica della macchina del fango: riportare qualcosa di assolutamente vero ma in modo da sottintendere qualcosa di falso, e chi la vuol capire la capisca.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "Evita le allitterazioni, anche se allettano gli allocchi.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "Il calcio è un rituale in cui i diseredati bruciano l'energia combattiva e la voglia di rivolta.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "Il cinema è un alto artificio che mira a costruire realtà alternative a spese di quella fattuale, che gli provvede solo il materiale grezzo.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "Il computer non è una macchina intelligente che aiuta le persone stupide, anzi, è una macchina stupida che funziona solo nelle mani delle persone intelligenti.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "Il grande problema della scuola oggi è insegnare ai giovani a filtrare le informazioni di Internet, cosa di cui non sono però capaci neppure i professori, perché sono neofiti in questo campo.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "Il paradiso dantesco è l'apoteosi del virtuale, degli immateriali, del puro software, senza il peso dell'hardware terrestre e infernale, di cui rimangono i cascami nel purgatorio.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "Io ho il diritto di scegliere la mia morte per il bene degli altri.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "L'ambiguità delle nostre lingue, la naturale imperfezione dei nostri idiomi, non rappresentano il morbo postbabelico dal quale l'umanità deve guarire, bensì la sola opportunità che Dio aveva dato ad Adamo, l'animale parlante.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "L'unico modo per riconoscere se un libro sui Templari è serio è controllare se finisce col 1314, data in cui il loro Gran Maestro viene bruciato sul rogo.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "La decadenza dei costumi non sta in ciò che fanno Lady D e l'amante, ma nel fatto che i lettori paghino per farselo raccontare.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "La filosofia è sempre una forma di alto dilettantismo, in cui qualcuno, per tanto che abbia letto, parla sempre di cose su cui non si è preparato abbastanza.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "La paranoia della cospirazione universale non finirà mai e non puoi stanarla perché non sai mai cosa c'è dietro. È una tentazione psicologica della nostra specie.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "La ripresa diretta non è mai una resa speculare dell'avvenimento che si svolge, ma sempre - se pur in certi casi in misura infinitesimale - una interpretazione di esso.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "La televisione di Stato è carismatica per eccellenza: il pubblico e i giornali rimangono sconvolti e affascinati da quello che avviene sulle tre reti nazionali, mentre da Berlusconi può avvenire qualsiasi cosa.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "Le opere letterarie ci invitano alla libertà dell'interpretazione, perché ci propongono un discorso dai molti piani di lettura e ci pongono di fronte alle ambiguità e del linguaggio e della vita.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "Le preoccupazioni della stampa europea non sono dovute a pietà e amore per l'Italia ma semplicemente al timore che l'Italia, come in un altro infausto passato, sia il laboratorio di esperimenti che potrebbero estendersi all'Europa intera.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "Ma non è scomparso uno dei Grandi Vecchi del secolo. Moravia è stato sino alla fine un Grande Giovane... Non si è costruito l'immagine del vate, dell'eroe, del maledetto o del martire, come altri protagonisti letterari del secolo.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "Mentre un saggio [...] tende ad arrivare a delle conclusioni, un romanzo mette in scena le contraddizioni.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "Noi usiamo continuamente la parola \"bello\" per dire \"una bella bistecca\", \"una bella giornata\", \"una bella notte d'amore\", \"un bel bambino\", e così via.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "Non credo che Benedetto XVI sia un grande filosofo, né un grande teologo, anche se generalmente viene rappresentato come tale.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "Ora, cos'è importante nel problema dell'accessibilità agli scaffali? È che uno dei malintesi che dominano la nozione di biblioteca è che si vada in biblioteca per cercare un libro di cui si conosce il titolo.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "Pensa a una trasmissione come Drive in, al suo ritmo, alla quantità di cose che riesce a far vedere in due minuti e paragona due minuti di Drive in a due minuti della vecchia televisione.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "Posso leggere la Bibbia, Omero o Dylan Dog per giorni e giorni senza annoiarmi.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "Prepararsi al domani vuole dire non solo capire come funziona oggi un programma elettronico ma concepire nuovi programmi.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "Quando un personaggio genera un nome comune, ha infranto la barriera dell'immortalità ed è entrato nel mito: si è un Calimero, come si è un Don Giovanni, un Casanova, un Don Chisciotte, una Cenerentola.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "Recentemente un discepolo pensoso (tale Critone) mi ha chiesto: \"Maestro, come si può bene appressarsi alla morte?\"", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "Scrivere un libro senza preoccuparsi della sua sopravvivenza sarebbe da imbecilli.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "Vedevo il volto di un uomo esposto alla gogna, spiato in ogni piega del labbro, esposto al ludibrio di milioni di spettatori. Questo tipo di gogna vale un ergastolo.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "Voglio [...] parlare della mia morte, e ammetterete che in questo caso ho qualche diritto all'esternazione.", Author = "Umberto Eco" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Umberto_Eco", Text = "Wikipedia ha anche un'altra proprietà: chiunque può correggere una voce che ritiene sbagliata. Ho fatto la prova per la voce che mi riguarda: conteneva un dato biografico impreciso, l'ho corretto e da allora la voce non contiene più quell'errore.", Author = "Umberto Eco" },
